class Solution:
    def isBipartite(self, graph: List[List[int]]) -> bool:
        color = [-1] * len(graph)
        for start in range(len(graph)):          # the graph may be disconnected
            if color[start] != -1:
                continue
            color[start] = 0
            queue = deque([start])
            while queue:
                u = queue.popleft()
                for v in graph[u]:
                    if color[v] == -1:
                        color[v] = 1 - color[u]  # opposite colour
                        queue.append(v)
                    elif color[v] == color[u]:   # same colour on an edge: odd cycle
                        return False
        return True
